"import openpyxl
from openpyxl import load_workbook

# Load the workbook
wb = load_workbook('output.xlsx')

# Get the sheets
sh1 = wb['SH1']
rp1 = wb['RP1']
merging = wb['merging']


def find_column(sheet, keyword):
    """Find column index (1-based) whose header (row 1) contains keyword."""
    keyword = keyword.lower()
    for col in range(1, sheet.max_column + 1):
        header = sheet.cell(row=1, column=col).value
        if header is not None and keyword in str(header).lower():
            return col
    return None


# Identify ID and QTY columns in each source sheet
sh1_id_col = find_column(sh1, 'id')
sh1_qty_col = find_column(sh1, 'qty')
rp1_id_col = find_column(rp1, 'id')
rp1_qty_col = find_column(rp1, 'qty')


def build_lookup(sheet, id_col, qty_col):
    """Return a dict mapping ID -> QTY from the given sheet."""
    lookup = {}
    if id_col is None or qty_col is None:
        return lookup
    for row in range(2, sheet.max_row + 1):
        id_val = sheet.cell(row=row, column=id_col).value
        qty_val = sheet.cell(row=row, column=qty_col).value
        if id_val is None:
            continue
        # Treat None or empty string as blank
        if qty_val is None or (isinstance(qty_val, str) and qty_val.strip() == ''):
            lookup[id_val] = None
        else:
            lookup[id_val] = qty_val
    return lookup


sh1_lookup = build_lookup(sh1, sh1_id_col, sh1_qty_col)
rp1_lookup = build_lookup(rp1, rp1_id_col, rp1_qty_col)


def resolve(lookup, key):
    """Return the QTY for the key, or '-' if missing / blank."""
    if key is None:
        return "-"
    if key not in lookup:
        return "-"
    val = lookup[key]
    if val is None:
        return "-"
    if isinstance(val, str) and val.strip() == '':
        return "-"
    return val


# Fill the merging sheet rows 2..11, columns C (3) and D (4)
for row in range(2, 12):
    id_val = merging.cell(row=row, column=2).value  # Column B
    try:
        merging.cell(row=row, column=3).value = resolve(sh1_lookup, id_val)
    except Exception:
        merging.cell(row=row, column=3).value = "-"
    try:
        merging.cell(row=row, column=4).value = resolve(rp1_lookup, id_val)
    except Exception:
        merging.cell(row=row, column=4).value = "-"

# Save the workbook
wb.save('output.xlsx')"
